'use strict';
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=(name,extra='')=>`<svg class="icon ${extra}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const B=(act,label,cls='text-action',icon='',disabled=false)=>`<button data-act="${act}" class="${cls}" ${disabled?'disabled':''}>${icon?I(icon):''}${label}</button>`;
const P=(tile,style='')=>`<span class="photo t${tile}" role="img" aria-label="${['山间湖泊','雨后街景','金色草原','潮汐海岸','林间小径','雪山木屋'][tile]}" ${style?`style="${style}"`:''}></span>`;
const notice=(text,type='',icon='info')=>`<div class="notice ${type}">${I(icon)}<span>${text}</span></div>`;
const note=text=>`<p class="note">${text}</p>`;
const title=(text,right='')=>`<div class="section-row"><h3 class="section-title">${text}</h3>${right}</div>`;
const list=(icon,label,sub,act,value='')=>`<button class="list-row" data-act="${act}">${I(icon)}<span class="list-copy"><strong>${label}</strong>${sub?`<small>${sub}</small>`:''}</span>${value?`<span class="list-value">${value}</span>`:''}${I('chevron','chev')}</button>`;
const row=(label,value)=>`<div class="list-row"><span class="list-copy"><strong>${label}</strong></span><span class="list-value">${value}</span></div>`;
const tabs=(items,current,action)=>`<div class="tabbar">${items.map(([id,label])=>B(`${action}:${id}`,label,id===current?'active':'')).join('')}</div>`;
const empty=(heading,text,button='',icon='image')=>`<div class="state-empty">${I(icon)}<h3>${heading}</h3><p>${text}</p>${button}</div>`;
const topbar=(heading,back='',right='',sub='')=>`<header class="app-topbar ${back?'secondary':''}">${back?B(back,'<span class="sr-only">返回</span>','icon-button','back'):''}<div><h2>${heading}</h2>${sub?`<p class="subheading">${sub}</p>`:''}</div><div class="spacer"></div>${right}</header>`;
const statusbar=()=>`<div class="statusbar"><span>9:41</span><span class="status-icons">${I('signal')}${I('wifi')}${I('battery','battery')}</span></div>`;
